'use strict'

import InputManager from '../service/input-manager'

// A pad on the screen for the phones and tablets: a cross, A, B and Start, as on the NES controller. A button
// sends the keydown / keyup of the key bound to its action, so the game, its inventory and its menus play as
// with a keyboard. Shown on touch screens only (pointer: coarse)
const DIRECTIONS = {
  up: InputManager.ACTION_LINK_MOVE_NORTH,
  down: InputManager.ACTION_LINK_MOVE_SOUTH,
  left: InputManager.ACTION_LINK_MOVE_WEST,
  right: InputManager.ACTION_LINK_MOVE_EAST
}
const BUTTONS = [
  ['b', 'B', InputManager.ACTION_LINK_USE_ITEM_B],
  ['a', 'A', InputManager.ACTION_LINK_USE_ITEM_A],
  ['start', 'START', InputManager.ACTION_START]
]
// The middle of the cross presses nothing; around it, 8 parts: a diagonal presses both ways (the vertical one
// wins in the game, as in the ROM)
const DEAD_ZONE = 0.18
const VIBRATION = 8
// Sizes of the pad: beside the game in landscape, under it in portrait (CSS pixels)
const MIN_SIDE = 140
const MAX_SIDE = 230
const MIN_BOTTOM = 190
const MAX_BOTTOM = 300

export function isTouchScreen () {
  return typeof window !== 'undefined' && !!window.matchMedia?.('(pointer: coarse)').matches
}

// What the cross presses for a touch at (dx, dy) from its middle, its radius being radius
export function crossDirections (dx, dy, radius) {
  if (Math.hypot(dx, dy) < DEAD_ZONE * radius) {
    return []
  }
  const sector = Math.round(Math.atan2(dy, dx) / (Math.PI / 4))
  return {
    0: ['right'],
    1: ['down', 'right'],
    2: ['down'],
    3: ['down', 'left'],
    4: ['left'],
    '-4': ['left'],
    '-3': ['up', 'left'],
    '-2': ['up'],
    '-1': ['up', 'right']
  }[sector]
}

function press (action, down) {
  const code = InputManager.getBinding(action)
  if (code) {
    document.dispatchEvent(new KeyboardEvent(down ? 'keydown' : 'keyup', { code, bubbles: true }))
  }
}

export class TouchControls {
  constructor (soundCheckbox, settings) {
    this.soundCheckbox = soundCheckbox
    this.settings = settings
    this.active = isTouchScreen()
    this.held = new Set()
    this.element = undefined
  }

  // What the page keeps for the pad around the game (CSS pixels)
  get reserved () {
    if (!this.active) {
      return { width: 0, height: 0 }
    }
    if (window.innerWidth > window.innerHeight) {
      return { width: 2 * this.side, height: 0 }
    }
    return { width: 0, height: this.bottom }
  }

  get side () {
    return Math.max(MIN_SIDE, Math.min(MAX_SIDE, window.innerWidth * 0.24))
  }

  get bottom () {
    return Math.max(MIN_BOTTOM, Math.min(MAX_BOTTOM, window.innerHeight * 0.38))
  }

  init () {
    if (!this.active) {
      return
    }
    document.body.classList.add('touch')
    this.element = document.createElement('div')
    this.element.className = 'touch-controls'
    this.element.innerHTML = `
      <div class="touch-cross"><span class="up"></span><span class="down"></span><span class="left"></span><span class="right"></span></div>
      <div class="touch-buttons">${BUTTONS.filter(([id]) => id !== 'start').map(([id, label]) => `<button type="button" class="touch-${id}">${label}</button>`).join('')}</div>
      <div class="touch-menu">
        <button type="button" class="touch-start">START</button>
        <button type="button" class="touch-sound" aria-label="Sound">♪</button>
        <button type="button" class="touch-fullscreen" aria-label="Full screen"><svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 6V1h5M10 1h5v5M15 10v5h-5M6 15H1v-5"/></svg></button>
        <button type="button" class="touch-settings" aria-label="Settings">⚙</button>
      </div>`
    document.body.append(this.element)
    this.listenCross(this.element.querySelector('.touch-cross'))
    for (const [id, , action] of BUTTONS) {
      this.listenButton(this.element.querySelector(`.touch-${id}`), action)
    }
    this.listenTap('.touch-sound', () => this.toggleSound())
    this.listenTap('.touch-settings', () => this.settings?.classList.toggle('open'))
    const fullscreen = this.element.querySelector('.touch-fullscreen')
    if (document.documentElement.requestFullscreen) {
      this.listenTap('.touch-fullscreen', () => document.fullscreenElement ? document.exitFullscreen() : document.documentElement.requestFullscreen())
    } else {
      fullscreen.remove()
    }
    // No zoom on a double tap, nor menu on a long one
    this.element.addEventListener('contextmenu', e => e.preventDefault())
    this.layout()
    window.addEventListener('resize', () => this.layout())
    this.showSound()
  }

  // Sizes of the pad, for the CSS
  layout () {
    this.element.style.setProperty('--touch-side', `${this.side}px`)
    this.element.style.setProperty('--touch-bottom', `${this.bottom}px`)
  }

  listenTap (selector, action) {
    this.element.querySelector(selector).addEventListener('pointerdown', e => {
      e.preventDefault()
      navigator.vibrate?.(VIBRATION)
      action()
    })
  }

  listenButton (button, action) {
    const release = e => {
      e.preventDefault()
      button.classList.remove('pressed')
      press(action, false)
    }
    button.addEventListener('pointerdown', e => {
      e.preventDefault()
      button.setPointerCapture?.(e.pointerId)
      button.classList.add('pressed')
      navigator.vibrate?.(VIBRATION)
      press(action, true)
    })
    button.addEventListener('pointerup', release)
    button.addEventListener('pointercancel', release)
  }

  // The finger can slide from a way to another without leaving the cross
  listenCross (cross) {
    const update = e => {
      const box = cross.getBoundingClientRect()
      const ways = crossDirections(e.clientX - box.left - box.width / 2, e.clientY - box.top - box.height / 2, box.width / 2)
      this.hold(cross, new Set(ways))
    }
    cross.addEventListener('pointerdown', e => {
      e.preventDefault()
      cross.setPointerCapture?.(e.pointerId)
      navigator.vibrate?.(VIBRATION)
      update(e)
    })
    cross.addEventListener('pointermove', e => {
      if (this.held.size > 0 || e.buttons) {
        update(e)
      }
    })
    const release = e => {
      e.preventDefault()
      this.hold(cross, new Set())
    }
    cross.addEventListener('pointerup', release)
    cross.addEventListener('pointercancel', release)
  }

  hold (cross, ways) {
    for (const way of this.held) {
      if (!ways.has(way)) {
        press(DIRECTIONS[way], false)
        cross.querySelector(`.${way}`).classList.remove('pressed')
      }
    }
    for (const way of ways) {
      if (!this.held.has(way)) {
        press(DIRECTIONS[way], true)
        cross.querySelector(`.${way}`).classList.add('pressed')
      }
    }
    this.held = ways
  }

  // The sound is the box of the page: browsers only let it play after a tap
  toggleSound () {
    if (!this.soundCheckbox) {
      return
    }
    this.soundCheckbox.checked = !this.soundCheckbox.checked
    this.soundCheckbox.dispatchEvent(new Event('change'))
    this.showSound()
  }

  showSound () {
    this.element?.querySelector('.touch-sound')?.classList.toggle('off', !this.soundCheckbox?.checked)
  }
}
