'use strict'

import resource from '../../resource'
import { TILE_WIDTH, DIRECTION_EAST, DIRECTION_WEST, DIRECTION_NORTH, DIRECTION_SOUTH, ENEMY_OCTOROK_RED, ENEMY_OCTOROK_RED_FAST, ENEMY_OCTOROK_BLUE, ENEMY_OCTOROK_BLUE_FAST, ENEMY_MOBLIN_RED, ENEMY_MOBLIN_BLUE, ENEMY_LYNEL_RED, ENEMY_LYNEL_BLUE, ENEMY_ARMOS, ENEMY_GHINI, NES_PIXEL } from '../../constant'
import { Enemy, DIRECTION_VECTORS, DIRECTIONS, STATE_SPAWNING, STATE_WAITING, STATE_HURT, randomInt, pick, isInside, drawImage, canWalkTo } from './common'
import { Rock, Arrow, Sword } from './projectile'

// Enemies that walk on the grid and shoot straight ahead: octoroks (rocks), moblins (arrows),
// lynels (swords). Life in hits of the wooden sword, speed in pixels per step, damage in hearts. How they turn
// (measured in the ROM, see chooseWay): turnRate, the chance out of 256 to face Link when he is in line
// ($041F), or chases, for those going after Link when he is near
export const WALKERS = {
  [ENEMY_OCTOROK_RED]: { sprite: 'octorok_red', life: 1, speed: 1, contactDamage: 0.5, shot: 'rock', turnRate: 0x70 },
  [ENEMY_OCTOROK_RED_FAST]: { sprite: 'octorok_red', life: 1, speed: 2, contactDamage: 0.5, shot: 'rock', turnRate: 0x70 },
  [ENEMY_OCTOROK_BLUE]: { sprite: 'octorok_blue', life: 2, speed: 1, contactDamage: 0.5, shot: 'rock', turnRate: 0xa0 },
  [ENEMY_OCTOROK_BLUE_FAST]: { sprite: 'octorok_blue', life: 2, speed: 2, contactDamage: 0.5, shot: 'rock', turnRate: 0xa0 },
  [ENEMY_MOBLIN_RED]: { sprite: 'moblin_red', life: 2, speed: 1, contactDamage: 0.5, shot: 'arrow', turnRate: 0xa0 },
  [ENEMY_MOBLIN_BLUE]: { sprite: 'moblin_blue', life: 3, speed: 1, contactDamage: 1, shot: 'arrow', turnRate: 0xa0 },
  [ENEMY_LYNEL_RED]: { sprite: 'lynel_red', life: 4, speed: 1, contactDamage: 1, shot: 'sword', color: 'red', shotDamage: 1, chases: true },
  [ENEMY_LYNEL_BLUE]: { sprite: 'lynel_blue', life: 6, speed: 1, contactDamage: 2, shot: 'sword', color: 'blue', shotDamage: 2, chases: true },
  // Woken from its statue only (see armos.js), it does not shoot
  [ENEMY_ARMOS]: { sprite: 'armos', life: 3, speed: 1, contactDamage: 1, chases: true },
  // See ghini.js
  [ENEMY_GHINI]: { sprite: 'ghini', life: 9, speed: 1, contactDamage: 1, turnRate: 0xff }
}

// Walkers walk on the grid of the tiles (16 NES pixels, measured on the octoroks) and only turn or stop on it
const GRID = TILE_WIDTH
// How they turn, on a point of the grid (bank 4, $80A4): with the chance of their turnRate, they face Link if he
// is in line with them within 8 NES pixels; otherwise, when their count of frames (0 to 255, at random) is over,
// they turn a quarter towards him. The chasers (bank 4, $8119: lynels, Armos) face him along the way he is the
// furthest, when it is less than $51 NES pixels
const IN_LINE = NES_PIXEL * 9
const CHASE_DISTANCE = NES_PIXEL * 0x51
const MAX_TURN_FRAMES = 255
const OPPOSITES = { [DIRECTION_EAST]: DIRECTION_WEST, [DIRECTION_WEST]: DIRECTION_EAST, [DIRECTION_NORTH]: DIRECTION_SOUTH, [DIRECTION_SOUTH]: DIRECTION_NORTH }
const isVertical = direction => direction === DIRECTION_NORTH || direction === DIRECTION_SOUTH

// What the walkers go after (bank 7, $EC92): Link, then, for as long, the point of the screen opposite him
// (255 - x, 255 - y in NES pixels, fixed when it starts), and so on, each for 0 to 7 times 10 frames at random
const TARGET_FRAMES = 10
const TARGET_TIMES = 7
const NES_TOP = 0x3d

export function updateTarget (map, link, random = Math.random) {
  map.targetFrames = (map.targetFrames ?? 0) - 1
  if (map.targetFrames <= 0) {
    map.targetFrames = randomInt(random, 0, TARGET_TIMES) * TARGET_FRAMES
    map.targetMirrored = !map.targetMirrored
    if (map.targetMirrored) {
      const x = 255 - (link.x - map.x) / NES_PIXEL
      const y = 255 - ((link.y - map.y) / NES_PIXEL + NES_TOP)
      map.target = { x: map.x + NES_PIXEL * x, y: map.y + NES_PIXEL * (y - NES_TOP) }
    }
  }
  if (!map.targetMirrored) {
    map.target = { x: link.x, y: link.y }
  }
}

// A new way for an enemy on a point of the grid (enemy: x, y, direction, turnFrames, random), after the target
// (Link, or the point opposite him, see updateTarget)
export function chooseWay (enemy, target, { turnRate = 0, chases = false }) {
  const dx = target.x - enemy.x
  const dy = target.y - enemy.y
  if (chases) {
    if (Math.abs(dy) >= Math.abs(dx)) {
      if (Math.abs(dy) < CHASE_DISTANCE) {
        enemy.direction = dy >= 0 ? DIRECTION_SOUTH : DIRECTION_NORTH
      }
    } else if (Math.abs(dx) < CHASE_DISTANCE) {
      enemy.direction = dx >= 0 ? DIRECTION_EAST : DIRECTION_WEST
    }
    return
  }
  if (Math.floor(enemy.random() * 256) <= turnRate) {
    if (Math.abs(dx) < IN_LINE) {
      enemy.direction = dy < 0 ? DIRECTION_NORTH : DIRECTION_SOUTH
      enemy.turnFrames = randomInt(enemy.random, 0, MAX_TURN_FRAMES)
      return
    }
    if (Math.abs(dy) < IN_LINE) {
      enemy.direction = dx >= 0 ? DIRECTION_EAST : DIRECTION_WEST
      enemy.turnFrames = randomInt(enemy.random, 0, MAX_TURN_FRAMES)
      return
    }
  }
  if (enemy.turnFrames > 0) {
    return
  }
  enemy.direction = isVertical(enemy.direction) ? (dx >= 0 ? DIRECTION_EAST : DIRECTION_WEST) : (dy < 0 ? DIRECTION_NORTH : DIRECTION_SOUTH)
  enemy.turnFrames = randomInt(enemy.random, 0, MAX_TURN_FRAMES)
}

// The way blocked (bank 7, $F1DF): a quarter turn one side or the other at random, then the other side, then
// back. False when it is walled in (it stays where it is)
export function avoidObstacle (enemy, map) {
  if (canWalkTo(map, enemy.x, enemy.y, enemy.direction)) {
    return true
  }
  const sides = isVertical(enemy.direction) ? [DIRECTION_EAST, DIRECTION_WEST] : [DIRECTION_NORTH, DIRECTION_SOUTH]
  const side = pick(enemy.random, sides)
  for (const direction of [side, OPPOSITES[side], OPPOSITES[enemy.direction]]) {
    if (canWalkTo(map, enemy.x, enemy.y, direction)) {
      enemy.direction = direction
      return true
    }
  }
  return false
}

// Chance, on each point of the grid, to stop and shoot
const THROW_CHANCE = 1 / 8
const AIM_STEPS = 30
const AFTER_THROW_STEPS = 15
const WALK_FRAME_PIXELS = 8

const STATE_ENTERING = 'entering'
const STATE_WALKING = 'walking'
const STATE_AIMING = 'aiming'

export { canWalkTo }

class Walker extends Enemy {
  constructor (type, x, y, direction, random = Math.random) {
    const config = WALKERS[type]
    super(type, x, y, config, random)
    this.config = config
    this.color = config.sprite.split('_')[1]
    this.speed = config.speed
    this.direction = direction

    this.state = STATE_WALKING
    this.delay = 0 // Before walking in, for the enemies arriving from the edges
    this.turnFrames = 0 // Before it turns towards Link (see chooseWay)
    this.walkedPixels = 0
    this.decidedAt = undefined
    this.rock = undefined // The last shot, still flying
  }

  static inCloud (type, x, y, random = Math.random) {
    const walker = new this(type, x, y, pick(random, DIRECTIONS), random)
    walker.setState(STATE_SPAWNING)
    return walker
  }

  static fromEdge (type, x, y, direction, delay, random = Math.random) {
    const walker = new this(type, x, y, direction, random)
    walker.setState(STATE_WAITING)
    walker.delay = delay
    return walker
  }

  isOnGrid (map) {
    return (this.x - map.x) % GRID === 0 && (this.y - map.y) % GRID === 0
  }

  canMove (map, direction) {
    return canWalkTo(map, this.x, this.y, direction)
  }

  // Out of its cloud: a free way at random, and a count of frames before turning
  start (map) {
    this.setState(STATE_WALKING)
    const free = DIRECTIONS.filter(direction => this.canMove(map, direction))
    if (free.length > 0) {
      this.direction = pick(this.random, free)
    }
    this.turnFrames = randomInt(this.random, 0, MAX_TURN_FRAMES)
  }

  // On a point of the grid: maybe shoot, maybe turn (see chooseWay, avoidObstacle). True when the walker stops,
  // to shoot or walled in
  decide (map, link) {
    // Once per point (it is still there after shooting)
    const position = `${this.x},${this.y}`
    if (this.decidedAt !== position) {
      this.decidedAt = position
      if (this.config.shot && !this.rock && this.random() < THROW_CHANCE) {
        this.setState(STATE_AIMING)
        return true
      }
      chooseWay(this, map.target ?? link, this.config)
    }
    return !avoidObstacle(this, map)
  }

  // Off the grid (after being pushed back), it goes on to the next point of it without looking
  walk (map, link) {
    for (let i = 0; i < this.speed; i++) {
      if (this.isOnGrid(map) && this.decide(map, link)) {
        return
      }
      const [dx, dy] = DIRECTION_VECTORS[this.direction]
      this.x += dx
      this.y += dy
      this.walkedPixels++
    }
  }

  // From outside the screen, straight in, over everything
  enter (map) {
    const [dx, dy] = DIRECTION_VECTORS[this.direction]
    this.x += dx * this.speed
    this.y += dy * this.speed
    this.walkedPixels += this.speed
    // Once on the screen, it goes on inwards for a while
    if (isInside(map, this.x, this.y, this.width, this.height)) {
      this.setState(STATE_WALKING)
      this.turnFrames = randomInt(this.random, 0, MAX_TURN_FRAMES)
    }
  }

  turnBack () {
    this.direction = OPPOSITES[this.direction]
  }

  // Walks again after being pushed back, even when hit while aiming
  hit (link, weapon) {
    super.hit(link, weapon)
    if (this.state === STATE_HURT) {
      this.resumeState = STATE_WALKING
    }
  }

  shoot (map) {
    const { shot, color, shotDamage } = this.config
    const projectile = shot === 'arrow'
      ? new Arrow(this.x, this.y, this.direction)
      : shot === 'sword' ? new Sword(this.x, this.y, this.direction, color, shotDamage) : new Rock(this.x, this.y, this.direction)
    map.projectiles.push(projectile)
    this.rock = projectile
  }

  act (map, link) {
    if (this.rock?.done) {
      this.rock = undefined
    }
    if (this.turnFrames > 0) {
      this.turnFrames--
    }
    switch (this.state) {
      case STATE_WAITING:
        if (this.steps >= this.delay) {
          this.setState(STATE_ENTERING)
        }
        break
      case STATE_ENTERING:
        this.enter(map)
        break
      case STATE_WALKING:
        this.walk(map, link)
        break
      case STATE_AIMING:
        if (this.steps === AIM_STEPS) {
          this.shoot(map)
        }
        if (this.steps >= AIM_STEPS + AFTER_THROW_STEPS) {
          this.setState(STATE_WALKING)
        }
        break
    }
  }

  drawBody (context) {
    const frame = Math.floor(this.walkedPixels / WALK_FRAME_PIXELS) % 2
    drawImage(context, resource.getSprite(`${this.config.sprite}_${this.direction}_move`), frame, this.x, this.y, this.width, this.height)
  }
}

// The first walker of the game (the tests and the editor still call it that)
const Octorok = Walker

export { Walker, Octorok }
